// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint256 targetSeed) public {
        amount = bound(amount, 1, address(c).balance + 100 ether);
        Receiver receiver = new Receiver();
        vm.deal(address(c), amount);
        vm.prank(address(this));
        uint256 preReceiver = address(receiver).balance;
        c.sendMoney(address(receiver), amount);
        uint256 postReceiver = address(receiver).balance;

        assertTrue(postReceiver - preReceiver == amount);
    }
}

contract Receiver {
    receive() external payable {}
}
